const norm = (s) => String(s || '')
  .replace(/Ɵ/g, 'ti').replace(/Ō/g, 'ft').replace(/Ņ/g, 'fk')
  .replace(/ﬁ/g, 'fi').replace(/ﬂ/g, 'fl').replace(/ﬀ/g, 'ff').replace(/ﬃ/g, 'ffi')
  .replace(/[–—]/g, '-').replace(/\r/g, '');

const form = $('Application Form').first();
const resumeText = norm($('Read Resume').first().json.text).toLowerCase();
const jdText = norm($input.first().json.text);
const myYears = parseFloat(String(form.json.experience_years || '').replace(/[^0-9.]/g, '')) || 0;
const myEmail = String(form.json.my_email || '').trim().toLowerCase();
const isPreview = String(form.json.mode || '').toLowerCase().startsWith('preview');
const resumeBinary = form.binary && form.binary.resume ? { resume: form.binary.resume } : {};

// Skills: counted only when BOTH the job and your resume mention them
const SKILLS = [
  ['Playwright', /playwright/], ['Cypress', /cypress/],
  ['API testing', /\bapi\b|postman|rest ?api/], ['Manual testing', /manual/],
  ['Functional testing', /functional/], ['Regression testing', /regression/],
  ['Sanity/Smoke testing', /sanity|smoke/], ['Integration testing', /integration/],
  ['E2E testing', /end[- ]to[- ]end|\be2e\b/], ['Automation', /automation/],
  ['AI/LLM testing', /\bllm|gen ?ai|generative|ai products|ai testing|ai-powered/],
  ['JavaScript/TypeScript', /javascript|typescript/], ['CI/CD', /ci\/cd|jenkins|github actions/],
  ['Agile/Scrum', /agile|scrum/], ['Jira/Azure DevOps', /jira|azure devops/],
  ['QA leadership', /\blead\b|leadership/], ['Defect management', /defect/],
];
// Hard blockers: job is rejected if it needs these and your resume does not mention them
const HARD = [
  ['Salesforce', /salesforce/], ['SAP', /\bsap\b/], ['Finacle', /finacle/],
  ['ETL/Data warehouse', /\betl\b|data warehouse|snowflake|databricks|great expectations/],
  ['Bluetooth', /bluetooth/], ['Wi-Fi/5G/Telecom', /wi-?fi|\b5g\b|o-ran/], ['Printers', /printer/],
  ['AR/VR', /ar\/vr|augmented reality|virtual reality/], ['LoadRunner/NeoLoad', /loadrunner|neoload/],
  ['TOSCA', /tosca/], ['Mainframe', /mainframe/], ['Kafka', /kafka/],
];
// Soft blockers: rejected only when the job also has none of your automation tools
const SOFT = [
  ['Java', /\bjava\b(?!script)/], ['C#', /c#/], ['Selenium', /selenium/], ['Python', /python|pytest/],
  ['JMeter', /jmeter/], ['Appium', /appium/],
];
const myTools = [/playwright/, /cypress/].filter((r) => r.test(resumeText));

const lines = jdText.split('\n');
const blocks = [];
let buf = [];
for (const line of lines) {
  const m = line.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
  if (m) {
    const content = buf.map((l) => l.trim()).filter((l) => l);
    if (content.length >= 3) blocks.push({ lines: content, email: m[0].toLowerCase() });
    buf = [];
  } else {
    buf.push(line);
  }
}

const rangeRe = /(\d+(?:\.\d+)?)\s*(?:-|to)\s*(\d+(?:\.\d+)?)\s*\+?\s*(?:yrs?|years?)/i;
const minRe = /(\d+(?:\.\d+)?)\s*\+?\s*(?:yrs?|years?)/i;

const seen = new Set();
const out = [];
for (const b of blocks) {
  const email = b.email;
  if (email === 'swtestingstudio@gmail.com' || email === myEmail || seen.has(email)) continue;
  const job = b.lines.join('\n').toLowerCase();

  let expIdx = -1, min = null, max = null;
  for (let i = 0; i < Math.min(8, b.lines.length); i++) {
    const r = b.lines[i].match(rangeRe);
    if (r) { expIdx = i; min = parseFloat(r[1]); max = parseFloat(r[2]); break; }
    const s = b.lines[i].match(minRe);
    if (s) { expIdx = i; min = parseFloat(s[1]); break; }
  }
  let location = b.lines[0] || '', company = b.lines[1] || '', role = b.lines[2] || '';
  if (expIdx >= 1) {
    role = b.lines[expIdx - 1];
    company = expIdx >= 2 ? b.lines[expIdx - 2] : '';
    location = expIdx >= 3 ? b.lines[0] : '';
  }

  // Experience fit (1 year tolerance either side)
  if (myYears && min !== null && myYears + 1 < min) continue;
  if (myYears && max !== null && myYears > max + 1) continue;

  const hard = HARD.filter(([, r]) => r.test(job) && !r.test(resumeText)).map(([n]) => n);
  if (hard.length) continue;
  const soft = SOFT.filter(([, r]) => r.test(job) && !r.test(resumeText)).map(([n]) => n);
  const hasMyTool = myTools.some((r) => r.test(job));
  if (soft.length && !hasMyTool) continue;

  const matched = SKILLS.filter(([, r]) => r.test(job) && r.test(resumeText)).map(([n]) => n);
  if (matched.length < 3) continue;

  seen.add(email);
  out.push({
    json: {
      recruiter_email: email,
      send_to: isPreview ? form.json.my_email : email,
      subject: (isPreview ? '[PREVIEW to ' + email + '] ' : '') + form.json.email_subject,
      company, role, location,
      experience_required: min === null ? '' : (max === null ? min + '+ yrs' : min + '-' + max + ' yrs'),
      reason: 'Matches: ' + matched.join(', '),
      full_name: form.json.full_name,
      phone: form.json.phone || '',
      cover_message: form.json.cover_message,
    },
    binary: resumeBinary,
  });
}
return out;
